insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tt-01', 't-theories', 1, 'يقدم معلم نجمة ذهبية لكل طالب يجيب إجابة صحيحة، فلاحظ ازدياد المشاركة. النظرية التي تفسر هذا السلوك:', '["البنائية","السلوكية","الإنسانية","المعرفية"]'::jsonb, 1, 'استخدام التعزيز الموجب (النجمة) لزيادة تكرار السلوك جوهر النظرية السلوكية (الإشراط الإجرائي عند سكنر).') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tt-02', 't-theories', 2, 'أعفت معلمة طالبةً مجتهدة من الواجب الإضافي لالتزامها المستمر، فازداد التزام الطالبات. هذا مثال على:', '["العقاب","التعزيز السالب","الإطفاء","التعميم"]'::jsonb, 1, 'التعزيز السالب: إزالة مثير غير محبب (الواجب الإضافي) بعد السلوك المرغوب لزيادة تكراره، وهو ليس عقاباً.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tt-03', 't-theories', 2, 'يبدأ معلم درسه الجديد بمخطط تمهيدي شامل يربط المعرفة الجديدة بما سبق تعلمه. هذا تطبيق لمفهوم:', '["المنظمات المتقدمة عند أوزوبل","الإشراط الكلاسيكي عند بافلوف","التعزيز المتقطع عند سكنر","النمذجة عند باندورا"]'::jsonb, 0, 'المنظم المتقدم إطار عام يقدم قبل الدرس ليربط المعرفة الجديدة بالبنية المعرفية السابقة (التعلم ذو المعنى عند أوزوبل).') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tt-04', 't-theories', 2, 'طفل في الخامسة يعتقد أن كوباً طويلاً رفيعاً يحوي عصيراً أكثر من كوب قصير عريض رغم تساوي الكميتين. المرحلة النمائية عند بياجيه:', '["الحسية الحركية","ما قبل العمليات","العمليات المادية","العمليات المجردة"]'::jsonb, 1, 'عدم إدراك ثبات الكمية من خصائص مرحلة ما قبل العمليات (2–7 سنوات).') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tt-05', 't-theories', 2, 'يستطيع طالب في الصف الخامس حل مسائل منطقية إذا ارتبطت بمواد محسوسة، ويصعب عليه التجريد. وفق بياجيه هو في مرحلة:', '["الحسية الحركية","ما قبل العمليات","العمليات المادية (المحسوسة)","العمليات المجردة"]'::jsonb, 2, 'مرحلة العمليات المادية (7–11 سنة): تفكير منطقي مرتبط بالمحسوسات، ويدرك فيها ثبات الكمية.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tt-06', 't-theories', 2, 'صمم معلم مهمة يعجز الطالب عن إنجازها وحده لكنه ينجزها بتوجيه بسيط منه أو من قرين متمكن. هذه المساحة تسمى عند فيجوتسكي:', '["التمثل","منطقة النمو الوشيك","الموازنة","التعلم الشرطي"]'::jsonb, 1, 'منطقة النمو الوشيك: المسافة بين ما ينجزه المتعلم مستقلاً وما ينجزه بمساعدة الأكثر خبرة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tt-07', 't-theories', 2, 'يقدم معلم دعماً مكثفاً في بداية تعلم مهارة ثم يسحبه تدريجياً كلما زاد تمكن الطلاب. هذا الأسلوب يسمى:', '["السقالات التعليمية","العصف الذهني","التعلم المبرمج","الاستقصاء الحر"]'::jsonb, 0, 'السقالات (التدعيم المؤقت) دعم يتناقص تدريجياً مع نمو الكفاءة، من تطبيقات البنائية الاجتماعية.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tt-08', 't-theories', 1, 'لاحظ الطلاب معلمهم يحافظ على النظافة ويلتقط المهملات، فبدؤوا يحاكونه دون توجيه لفظي. النظرية المفسرة:', '["السلوكية الكلاسيكية","التعلم الاجتماعي بالملاحظة","الجشطلت","المعرفية"]'::jsonb, 1, 'التعلم بالملاحظة والتقليد لنموذج (قدوة) هو جوهر نظرية باندورا في التعلم الاجتماعي.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tt-09', 't-theories', 2, 'وفق ترتيب مراحل التعلم بالملاحظة عند باندورا:', '["الانتباه ثم الاحتفاظ ثم إعادة الإنتاج ثم الدافعية","الدافعية ثم الانتباه ثم الأداء ثم الاحتفاظ","الاحتفاظ ثم الانتباه ثم الدافعية ثم الأداء","الأداء ثم الانتباه ثم الاحتفاظ ثم الدافعية"]'::jsonb, 0, 'يبدأ التعلم بالملاحظة بالانتباه للنموذج، ثم الاحتفاظ بالسلوك في الذاكرة، ثم القدرة على إعادة إنتاجه، وأخيراً الدافعية لأدائه.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tt-10', 't-theories', 2, 'جاء طالب إلى المدرسة دون فطور ويشكو نعاساً، فقدمت له المدرسة وجبة قبل مطالبته بالتركيز في الدرس. هذا التصرف يستند إلى:', '["هرم ماسلو للحاجات","قانون الأثر لثورندايك","منحنى النسيان","نظرية الذكاءات المتعددة"]'::jsonb, 0, 'وفق ماسلو لا يمكن الارتقاء لحاجات التعلم العليا قبل إشباع الحاجات الفسيولوجية الأساسية.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tt-11', 't-theories', 2, 'معلم يرى أن دوره تهيئة الأنشطة والمواقف ليبني الطلاب فهمهم بأنفسهم انطلاقاً من خبراتهم. هذا التوجه يمثل النظرية:', '["السلوكية","البنائية","الاجتماعية","الإجرائية"]'::jsonb, 1, 'البنائية ترى المتعلم بانياً نشطاً لمعرفته، والمعلم ميسراً لا ملقناً.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tt-12', 't-theories', 3, 'طالب يخاف من حصة الرياضيات لأن معلماً سابقاً كان يوبخه فيها باستمرار، فصار مجرد دخول المعلم الجديد بكتاب الرياضيات يثير قلقه. التفسير الأدق:', '["إشراط كلاسيكي (اقتران المثير بالانفعال)","تعزيز سالب","تعلم بالاستبصار","نمذجة"]'::jsonb, 0, 'اقترن مثير محايد (حصة/كتاب الرياضيات) بمثير منفر (التوبيخ) فصار يستدعي الانفعال ذاته — إشراط كلاسيكي.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tt-13', 't-theories', 2, '«اعتقاد الطالب بقدرته على النجاح في مهمة ما» يعرف بـ:', '["مفهوم الذات الأكاديمي","الكفاءة الذاتية","الدافعية الخارجية","التمركز حول الذات"]'::jsonb, 1, 'الكفاءة الذاتية (عند باندورا) اعتقاد الفرد بقدرته على تنفيذ مهمة بنجاح، وترفع المثابرة والإنجاز.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tt-14', 't-theories', 3, 'عدّل طفل مفهومه عن «الطيور» بعد أن عرف أن النعامة طائر لا يطير، فأعاد بناء تصنيفه. العملية التي حدثت وفق بياجيه:', '["التمثل","المواءمة","الاسترجاع","التعميم"]'::jsonb, 1, 'المواءمة: تعديل البنية المعرفية القائمة لتستوعب خبرة جديدة لا تنسجم معها. أما التمثل فإدخال الخبرة في البنية دون تعديلها.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tt-15', 't-theories', 2, 'معلم يهتم بمشاعر طلابه وتقديرهم لذواتهم ويرى أن التعلم الحقيقي ينبع من داخل المتعلم لتحقيق ذاته. توجهه يمثل النظرية:', '["الإنسانية","السلوكية","المعرفية","الترابطية"]'::jsonb, 0, 'النظرية الإنسانية (ماسلو وروجرز) تركز على المشاعر والحاجات وتحقيق الذات.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tt-16', 't-theories', 3, 'توقف معلم عن الالتفات للطالب الذي يجيب دون استئذان مع تعزيز من يرفع يده، فتراجع السلوك تدريجياً. الأسلوب المستخدم مع السلوك غير المرغوب:', '["العقاب البدني","الإطفاء","التعزيز المتواصل","التعميم"]'::jsonb, 1, 'الإطفاء: حجب التعزيز (الانتباه) الذي كان يديم السلوك حتى يتلاشى.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tt-17', 't-theories', 2, 'في التعلم بالاكتشاف عند برونر، يمر تمثيل المعرفة بالترتيب:', '["رمزي ثم صوري ثم عملي","عملي ثم صوري ثم رمزي","صوري ثم عملي ثم رمزي","رمزي ثم عملي ثم صوري"]'::jsonb, 1, 'يبدأ التمثيل عملياً (بالأداء والمحسوس)، ثم صورياً (بالصور)، ثم رمزياً (باللغة والرموز المجردة).') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tt-18', 't-theories', 2, 'يستخدم معلم أسلوب تجزئة المادة لخطوات صغيرة متدرجة يتلو كلَّ خطوة تغذيةٌ راجعة فورية وتعزيز. هذا يعرف بـ:', '["التعلم المبرمج","العصف الذهني","التعلم التعاوني","الاستقصاء"]'::jsonb, 0, 'التعلم المبرمج تطبيق سلوكي (سكنر): خطوات صغيرة + استجابة نشطة + تغذية فورية + تعزيز.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tt-19', 't-theories', 3, 'طالب متميز في تنظيم وقته ومراقبة فهمه وتقويم استراتيجياته الذاتية أثناء المذاكرة. هذه المهارات تسمى:', '["مهارات ما وراء المعرفة","الذكاء الاجتماعي","المهارات الحركية","الاستدلال الشرطي"]'::jsonb, 0, 'ما وراء المعرفة: وعي المتعلم بعمليات تفكيره وتخطيطها ومراقبتها وتقويمها.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tt-20', 't-theories', 1, 'وفق قانون الأثر عند ثورندايك، السلوك الذي تعقبه حالة ارتياح:', '["يضعف تدريجياً","يميل إلى التكرار والتقوية","ينطفئ فوراً","لا يتأثر"]'::jsonb, 1, 'قانون الأثر: الارتباطات المتبوعة بارتياح تقوى، والمتبوعة بضيق تضعف.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tg-01', 't-growth', 1, 'معلم صف أول ابتدائي يكثر من الألعاب الحركية والوسائل المحسوسة ويقصّر زمن النشاط الواحد. هذا يراعي:', '["خصائص النمو للمرحلة","ميوله الشخصية","تقليل التكاليف","رغبة الإدارة"]'::jsonb, 0, 'أطفال المرحلة الابتدائية الدنيا يتعلمون بالمحسوس ويميلون للحركة وتقصر فترة انتباههم.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tg-02', 't-growth', 2, 'طالب في المرحلة المتوسطة صار شديد الحساسية للنقد ويتأثر برأي أقرانه أكثر من والديه. هذا سلوك:', '["شاذ يستدعي الإحالة الفورية","طبيعي من خصائص المراهقة المبكرة","إعاقة انفعالية","تأخر نمائي"]'::jsonb, 1, 'تعاظم تأثير جماعة الرفاق والحساسية للنقد من الخصائص الطبيعية للمراهقة المبكرة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tg-03', 't-growth', 2, 'أنسب أسلوب لتوجيه سلوك طالب مراهق أخطأ أمام زملائه:', '["توبيخه أمام الصف ليرتدع الجميع","تجاهل الخطأ نهائياً","التنبيه العام دون تخصيص ثم الحديث معه على انفراد","إبلاغ ولي أمره فوراً قبل الحديث معه"]'::jsonb, 2, 'المراهق شديد الحساسية لماء وجهه أمام أقرانه؛ فالتوجيه الفردي بعيداً عن الزملاء أكثر أثراً وأقل ضرراً.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tg-04', 't-growth', 2, 'في المرحلة الثانوية، يُنصح المعلم بربط الدروس بـ:', '["الألعاب الحسية البسيطة","أهداف الطلاب المستقبلية والقضايا الواقعية","التلقين المباشر فقط","القصص الخيالية للأطفال"]'::jsonb, 1, 'طلاب الثانوية اكتمل لديهم التفكير المجرد ويهتمون بالمستقبل المهني والقضايا الكبرى.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tg-05', 't-growth', 1, 'وجود اختلافات بين طلاب الصف الواحد في القدرات والميول وسرعة التعلم يعرف بـ:', '["الفروق الفردية","التأخر الدراسي","صعوبات التعلم","التسرب"]'::jsonb, 0, 'الفروق الفردية اختلافات كمية طبيعية بين المتعلمين في الاستعدادات والقدرات والميول.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tg-06', 't-growth', 2, 'أفضل استجابة تعليمية للفروق الفردية داخل الصف:', '["توحيد الأنشطة للجميع تحقيقاً للعدل","التعليم المتمايز بتنويع المحتوى والعمليات والمنتجات","خفض مستوى المحتوى للجميع","الاهتمام بالمتفوقين فقط"]'::jsonb, 1, 'التمايز يقدم مسارات متعددة تناسب استعدادات الطلاب المختلفة؛ فالعدل ليس التطابق بل إعطاء كلٍّ ما يناسبه.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tg-07', 't-growth', 2, 'طالب يفهم الدرس بصورة أفضل عند رؤية الخرائط والمخططات والصور. نمط تعلمه الغالب:', '["سمعي","بصري","حركي","اجتماعي"]'::jsonb, 1, 'المتعلم البصري يعتمد على الصور والرسوم والألوان والمخططات في المعالجة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tg-08', 't-growth', 2, 'طالب بارع في تحليل الأنماط العددية وحل المسائل المنطقية. الذكاء البارز لديه وفق جاردنر:', '["اللغوي","المنطقي الرياضي","الحركي","الموسيقي"]'::jsonb, 1, 'الذكاء المنطقي الرياضي يظهر في التعامل مع الأرقام والاستدلال والأنماط.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tg-09', 't-growth', 2, 'التطبيق التربوي الصحيح لنظرية الذكاءات المتعددة:', '["تصنيف الطلاب في شعب حسب ذكاء واحد","تنويع الأنشطة ليجد كل طالب مدخلاً يناسب ذكاءه","إلغاء الاختبارات الكتابية نهائياً","تدريس الموهوبين فقط بها"]'::jsonb, 1, 'النظرية تدعو لتعدد مداخل التعلم وعرض المحتوى بطرائق متنوعة، لا لوصم الطلاب بنوع واحد.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tg-10', 't-growth', 2, 'طالب يذاكر حباً في الفهم والمعرفة دون انتظار مكافأة. دافعيته:', '["خارجية","داخلية","سلبية","اجتماعية"]'::jsonb, 1, 'الدافعية الداخلية تنبع من الرغبة الذاتية والاستمتاع بالتعلم، وهي أبقى أثراً من الخارجية.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tg-11', 't-growth', 3, 'لإثارة دافعية طلاب منخفضي التحصيل، الأفضل أن يبدأ المعلم بـ:', '["مهام صعبة جداً لتحدي قدراتهم","مهام قصيرة قابلة للإنجاز تحقق نجاحات مبكرة","حرمانهم من الأنشطة حتى يتحسنوا","مقارنتهم بالمتفوقين باستمرار"]'::jsonb, 1, 'النجاحات الصغيرة المبكرة تبني الكفاءة الذاتية وتكسر توقع الفشل؛ والمقارنات السلبية تحطم الدافعية.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tg-12', 't-growth', 2, 'من الممارسات الخاطئة في التعامل مع الدافعية:', '["ربط التعلم بحياة الطالب","التغذية الراجعة الفورية","التهديد المستمر بالاختبارات والعقوبات","تحديد أهداف واضحة قريبة"]'::jsonb, 2, 'التهديد يولد قلقاً معيقاً وارتباطاً انفعالياً سالباً بالمادة، وقد يدفع للغش أو التجنب.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tg-13', 't-growth', 3, 'مبدأ صحيح من مبادئ النمو الإنساني:', '["النمو يسير بسرعة ثابتة في كل المراحل","تتأثر مظاهر النمو بالوراثة دون البيئة","النمو عملية مستمرة متدرجة تتفاوت سرعتها بين المراحل","مظاهر النمو مستقلة لا يؤثر بعضها في بعض"]'::jsonb, 2, 'النمو مستمر ومتدرج ومتفاوت السرعة، وتتفاعل فيه الوراثة والبيئة، ومظاهره متداخلة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tg-14', 't-growth', 2, 'لاحظت معلمة أن إحدى طالبات المرحلة المتوسطة انطوت فجأة وتدهور تحصيلها بشكل حاد ومستمر. التصرف السليم:', '["تجاهل الأمر لأنه سيزول","إحالتها للموجهة الطلابية مع متابعة الحالة","توبيخها لتحسين مستواها","إخبار الطالبات بمشكلتها ليساعدنها"]'::jsonb, 1, 'التغير الحاد المفاجئ مؤشر يستدعي تدخل المختص (الموجه الطلابي) مع الحفاظ على الخصوصية والمتابعة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tp-01', 't-planning', 1, 'الفائدة الأهم للتخطيط اليومي للدرس:', '["إرضاء المشرف التربوي","تنظيم عمل المعلم وتحديد وجهة التعلم وتقويمه","ملء السجلات الرسمية","إشغال وقت المعلم"]'::jsonb, 1, 'التخطيط يحدد الأهداف والإجراءات والتقويم، فيعطي الدرس اتجاهاً واضحاً — وليس غايةً شكلية.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tp-02', 't-planning', 1, 'الترتيب الصحيح لمستويات الأهداف من الأعم إلى الأخص:', '["السلوكية ثم العامة ثم الغايات","الغايات ثم الأهداف العامة ثم الأهداف السلوكية","العامة ثم الغايات ثم السلوكية","السلوكية ثم الغايات ثم العامة"]'::jsonb, 1, 'الغايات أعم (مستوى الدولة)، تليها الأهداف العامة (المقرر)، ثم الخاصة/السلوكية (الدرس).') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tp-03', 't-planning', 2, 'أي الصياغات الآتية هدف سلوكي صحيح؟', '["أن يعرف الطالب أهمية الصلاة","أن يشرح المعلم أركان الإسلام","أن يعدد الطالب ثلاثة من أركان الإسلام دون الرجوع للكتاب","تنمية حب المادة لدى الطلاب"]'::jsonb, 2, 'صياغة الهدف السلوكي: أن + فعل قابل للقياس + الطالب + المحتوى + المعيار. «يعرف» غير قابل للملاحظة، والهدف يصف سلوك المتعلم لا المعلم.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tp-04', 't-planning', 2, 'الخطأ في الهدف: «أن يفهم الطالب قواعد السلامة ويطبقها في المختبر»:', '["ذكر الطالب","فعل غير قابل للقياس ودمج ناتجين في هدف واحد","تحديد مكان التطبيق","قابليته للقياس التام"]'::jsonb, 1, '«يفهم» فعل غير إجرائي، وجمع (يفهم ويطبق) يدمج ناتجين؛ والهدف الجيد يقيس ناتجاً واحداً بفعل ظاهر.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tp-05', 't-planning', 1, 'الترتيب الصحيح لمستويات المجال المعرفي في تصنيف بلوم المعدل:', '["تذكر، فهم، تطبيق، تحليل، تقويم، إبداع","فهم، تذكر، تحليل، تطبيق، إبداع، تقويم","تذكر، تطبيق، فهم، تقويم، تحليل، إبداع","إبداع، تقويم، تحليل، تطبيق، فهم، تذكر"]'::jsonb, 0, 'يتدرج التصنيف المعدل من التذكر إلى الإبداع (بعد أن كان التقويم قمة التصنيف القديم).') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tp-06', 't-planning', 2, '«أن يقارن الطالب بين التعلم التعاوني والتعلم الفردي من حيث الأدوار» — مستوى الهدف في تصنيف بلوم:', '["التذكر","الفهم","التطبيق","الإبداع"]'::jsonb, 1, 'المقارنة وبيان أوجه الشبه والاختلاف من أفعال مستوى الفهم (وقد ترقى للتحليل إذا تعمقت في العلاقات)؛ في صيغتها البسيطة هذه تصنف فهماً.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tp-07', 't-planning', 2, '«أن يصمم الطالب تجربة جديدة لإثبات تمدد المعادن بالحرارة» — مستوى الهدف:', '["التطبيق","التحليل","الإبداع","التذكر"]'::jsonb, 2, 'التصميم والإنتاج الجديد قمة الهرم المعرفي (الإبداع).') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tp-08', 't-planning', 2, '«أن يحل الطالب مسألة على مساحة المثلث باستخدام القانون» — مستوى الهدف:', '["التذكر","الفهم","التطبيق","التقويم"]'::jsonb, 2, 'استخدام قاعدة أو قانون في موقف جديد هو مستوى التطبيق.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tp-09', 't-planning', 2, '«أن يحكم الطالب على مقال ناقداً حججه بمعايير محددة» — مستوى الهدف:', '["الفهم","التقويم","التذكر","التطبيق"]'::jsonb, 1, 'إصدار الأحكام والنقد والتبرير وفق معايير هو مستوى التقويم.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tp-10', 't-planning', 2, 'هدف «أن يقدّر الطالب جهود العلماء المسلمين» ينتمي إلى المجال:', '["المعرفي","الوجداني","النفس حركي","المهاري"]'::jsonb, 1, 'التقدير والاتجاهات والميول والقيم من المجال الوجداني (الانفعالي).') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tp-11', 't-planning', 2, 'هدف «أن يرسم الطالب خريطة المملكة بدقة» ينتمي إلى المجال:', '["الوجداني","المعرفي","النفس حركي (المهاري)","الاجتماعي"]'::jsonb, 2, 'الرسم أداء عملي حركي منسق، فهو من المجال النفس حركي.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
